import{_ as i,C as r,o as n,c as s,j as d,a as e,E as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"对话框","description":"","frontmatter":{},"headers":[],"relativePath":"components/dialog.md","filePath":"components/dialog.md","lastUpdated":1787365442000}'),h={name:"components/dialog.md"},p={id:"对话框",tabindex:"-1"};function g(b,t,u,x,m,f){const l=r("Badge"),a=r("XhDemo");return n(),s("div",null,[d("h1",p,[t[0]||(t[0]=e("对话框 ",-1)),o(l,{type:"info",text:"dialog"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#对话框","aria-label":'Permalink to "对话框 <Badge type="info" text="dialog" />"'},"​",-1))]),t[3]||(t[3]=c('<p>浮在页面之上的一层，通常需要用户处理完才能回到下面。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>需要用户做出决定且不能忽略（确认删除、填一段必要信息）。</li><li>一段独立的子任务，完成后回到原处。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是提示一条结果：用<a href="./toast">轻提示</a>。</li><li>内容是页面主流程的一部分：直接展开在页面里。</li><li>内容很长或是一整个表单：用<a href="./drawer">抽屉</a>或单独一页。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>modal</code> 决定是否锁住下层：非模态时下面照常可交互。</li><li>焦点进入时落在 <code>initialFocus</code>，关闭后归还触发器。</li><li><code>closeOnEscape</code> 与 <code>closeOnInteractOutside</code> 各自可关——填了一半的表单不该点一下外面就没了。</li><li>内容区可以内部滚动，标题栏可以拖动挪窗口。</li><li>另有命令式服务，业务代码一次调用即弹出。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>不传 open 即为非受控；Esc 或点遮罩关闭，关闭后焦点回到触发按钮</p>',10)),o(a,{src:"dialog/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[5]||(t[5]=d("p",null,"传了 open 就由宿主说了算，组件自己不再改状态；Esc、点遮罩、按叉都只回写 open",-1)),o(a,{src:"dialog/02-controlled"}),t[6]||(t[6]=d("h3",{id:"警示对话框",tabindex:"-1"},[e("警示对话框 "),d("a",{class:"header-anchor",href:"#警示对话框","aria-label":'Permalink to "警示对话框"'},"​")],-1)),t[7]||(t[7]=d("p",null,"role=alertdialog 交给读屏更强的语气；关掉 Esc 与点遮罩后，只剩里面这两颗按钮能走出去",-1)),o(a,{src:"dialog/03-alert"}),t[8]||(t[8]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[9]||(t[9]=d("p",null,"size 落成 content 的 data-size，只改面板的最大宽度；三档各自一个对话框，点开才看得出宽窄",-1)),o(a,{src:"dialog/04-size"}),t[10]||(t[10]=d("h3",{id:"内容滚动",tabindex:"-1"},[e("内容滚动 "),d("a",{class:"header-anchor",href:"#内容滚动","aria-label":'Permalink to "内容滚动"'},"​")],-1)),t[11]||(t[11]=d("p",null,"标题与底部操作留在原处，只有中间那块长文在自己的框里滚",-1)),o(a,{src:"dialog/05-scroll"}),t[12]||(t[12]=d("h3",{id:"异步确认",tabindex:"-1"},[e("异步确认 "),d("a",{class:"header-anchor",href:"#异步确认","aria-label":'Permalink to "异步确认"'},"​")],-1)),t[13]||(t[13]=d("p",null,"提交期间按钮转圈，Esc 与点遮罩这两条出口一并封住，落定之后才把 open 写回 false",-1)),o(a,{src:"dialog/06-async"}),t[14]||(t[14]=d("h3",{id:"命令式确认框",tabindex:"-1"},[e("命令式确认框 "),d("a",{class:"header-anchor",href:"#命令式确认框","aria-label":'Permalink to "命令式确认框"'},"​")],-1)),t[15]||(t[15]=d("p",null,"一次函数调用把描述符推进表里并展开对话框；拿回的对象随后可改标题、正文与按钮状态，表里就是当前所有实例",-1)),o(a,{src:"dialog/07-imperative"}),t[16]||(t[16]=d("h3",{id:"拖动标题栏挪窗口",tabindex:"-1"},[e("拖动标题栏挪窗口 "),d("a",{class:"header-anchor",href:"#拖动标题栏挪窗口","aria-label":'Permalink to "拖动标题栏挪窗口"'},"​")],-1)),t[17]||(t[17]=d("p",null,"指针按在标题上，顺着 DOM 找到 content 部件，把累计位移写进它的 translate；入场动画走的是 transform，两者互不覆盖",-1)),o(a,{src:"dialog/08-draggable"}),t[18]||(t[18]=d("h3",{id:"命令式服务",tabindex:"-1"},[e("命令式服务 "),d("a",{class:"header-anchor",href:"#命令式服务","aria-label":'Permalink to "命令式服务"'},"​")],-1)),t[19]||(t[19]=d("p",null,"createDialogService 的 confirm 与单按钮预设：一行调用弹出，onOk 返回 Promise 时确认钮自动 pending 并拦住关闭；多次调用排队顺次弹",-1)),o(a,{src:"dialog/09-service"}),t[20]||(t[20]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-dialog&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhDialogCloseTrigger</code> <code>XhDialogContent</code> <code>XhDialogDescription</code> <code>XhDialogRoot</code> <code>XhDialogTitle</code> <code>XhDialogTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useDialog</code></td></tr><tr><td>状态机</td><td><code>dialogMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/dialog.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;dialog&quot;</code>：<code>trigger</code> · <code>backdrop</code> · <code>positioner</code> · <strong><code>content</code></strong> · <code>title</code> · <code>description</code> · <code>close-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>modal</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>role</code></td><td><code>&#39;dialog&#39; | &#39;alertdialog&#39;</code></td><td></td><td></td></tr><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>restoreFocus</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>initialFocus</code></td><td><code>string</code></td><td></td><td>展开后先聚焦到 content 内匹配此选择器的元素；选择器不匹配时回落默认聚焦顺序。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。只换 content 的最大宽度，落在 content 上（本组件没有 root 部件）。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;DialogTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: DialogOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>DialogOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhDialogRoot</code></td><td><code>default</code></td><td><code>DialogRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>TOGGLE</code> · <code>CLOSE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useDialog</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getBackdropProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>打开对话框并把焦点移入 content</td></tr><tr><td><code>Escape</code></td><td>open</td><td>关闭并把焦点还给 trigger</td></tr><tr><td><code>Tab</code></td><td>open</td><td>在 content 内向后循环焦点</td></tr><tr><td><code>Shift+Tab</code></td><td>open</td><td>在 content 内向前循环焦点</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>props.role</td></tr><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>props.translations.close</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/dialog.css</code> 按部件选择：<code>[data-scope=&quot;dialog&quot;][data-part=&quot;trigger&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-position</code></td><td>&#39;center&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-dialog-backdrop-bg</code> · <code>--xh-dialog-backdrop-layer</code> · <code>--xh-dialog-bg</code> · <code>--xh-dialog-close-bg-active</code> · <code>--xh-dialog-close-bg-hover</code> · <code>--xh-dialog-close-radius</code> · <code>--xh-dialog-close-size</code> · <code>--xh-dialog-description-fg</code> · <code>--xh-dialog-fg</code> · <code>--xh-dialog-gap</code> · <code>--xh-dialog-icon-size</code> · <code>--xh-dialog-layer</code> · <code>--xh-dialog-max-w</code> · <code>--xh-dialog-px</code> · <code>--xh-dialog-py</code> · <code>--xh-dialog-radius</code> · <code>--xh-dialog-shadow</code> · <code>--xh-dialog-title-fg</code> · <code>--xh-dialog-title-font-size</code> · <code>--xh-dialog-title-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-dialog-in</code> · <code>xh-dialog-out</code> · <code>xh-fade-in</code> · <code>xh-fade-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>内容区套<a href="./scroll-area">滚动区域</a>；按钮行用<a href="./button-group">按钮组</a>；确认类的轻量场景改用<a href="./popconfirm">弹出确认</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标题写这次要做什么，别写&quot;提示&quot;。</li><li>确认按钮的文字写具体动作（&quot;删除&quot;），不写&quot;确定&quot;。</li><li>破坏性操作用危险语气，并让取消是默认焦点。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>对话框里再开对话框。</li><li>点外面就关，而里面有未保存的输入。</li></ul>',48))])}const k=i(h,[["render",g]]);export{P as __pageData,k as default};
